package com.employee.servlet;

import com.employee.config.DatabaseConnection;
import com.employee.util.PasswordUtil;
import com.employee.util.PayrollCalculator;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.*;
import java.io.IOException;
import java.sql.*;
import java.time.LocalDate;
import java.math.BigDecimal;
import java.util.UUID;

/** Small, beginner-readable controller for the local educational application. */
@WebServlet(urlPatterns={"/app","/login","/logout"})
public class AppServlet extends HttpServlet {
    private String esc(String s) { return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;"); }
    private void page(HttpServletResponse r,String title,String body) throws IOException { r.setContentType("text/html;charset=UTF-8"); r.getWriter().print("<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>"+esc(title)+" - Demo Company</title><link rel='stylesheet' href='css/style.css'></head><body><header><a href='app'>Demo Company - People &amp; Payroll</a><span>Employee Payroll &amp; HR Management</span></header><main>"+body+"</main></body></html>"); }
    private String csrf(HttpSession s) { String token=(String)s.getAttribute("csrf"); if(token==null){token=UUID.randomUUID().toString();s.setAttribute("csrf",token);} return token; }
    @Override protected void doGet(HttpServletRequest q,HttpServletResponse r) throws IOException {
        String path=q.getServletPath();
        if(path.equals("/logout")){r.sendError(HttpServletResponse.SC_METHOD_NOT_ALLOWED);return;}
        if(path.equals("/login")){page(r,"Sign in","<section class='panel login'><h1>Welcome back</h1><p>Sign in to manage your team.</p>"+(q.getParameter("error")!=null?"<p class='error'>Username or password was not recognized.</p>":"")+"<form method='post' action='login'><label>Username<input name='username' required maxlength='80' autocomplete='username'></label><label>Password<input type='password' name='password' required autocomplete='current-password'></label><button>Sign in</button></form></section>");return;}
        Object user=q.getSession().getAttribute("user"); if(user==null){r.sendRedirect("login");return;}
        String role=(String)q.getSession().getAttribute("role"), module=q.getParameter("view"); if(module==null)module="dashboard";
        String menu="<nav><a href='app'>Overview</a><a href='app?view=employees'>Employees</a><a href='app?view=departments'>Departments</a><a href='app?view=attendance'>Attendance</a><a href='app?view=leaves'>Leave requests</a><a href='app?view=salaries'>Salary structures</a><a href='app?view=payroll'>Payroll</a><a href='app?view=payslips'>Payslips</a><a href='app?view=reports'>Reports</a><form method='post' action='logout' class='logout-form'><input type='hidden' name='csrf' value='"+csrf(q.getSession())+"'><button type='submit'>Sign out</button></form></nav>";
        try(Connection c=DatabaseConnection.getConnection()) {
            String content="";
            if(module.equals("dashboard")){ content="<h1>Good day, "+esc(user.toString())+"</h1><p class='muted'>A clear view of your people operations.</p><div class='cards'>"+card(c,"Active employees","SELECT COUNT(*) FROM employees WHERE status='ACTIVE'")+card(c,"Departments","SELECT COUNT(*) FROM departments WHERE active=1")+card(c,"Present today","SELECT COUNT(*) FROM attendance WHERE attendance_date=CURRENT_DATE AND status='PRESENT'")+card(c,"Pending leave","SELECT COUNT(*) FROM leave_requests WHERE status='PENDING'")+card(c,"Payroll this month","SELECT COUNT(*) FROM payroll WHERE payroll_month=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')")+"</div><section class='panel'><h2>Getting started</h2><p>Use the sections above to record employee, attendance and leave information, then prepare payroll.</p></section>"; }
            else if(module.equals("employees")){require(role,"ADMIN","HR_STAFF"); content="<h1>Employees</h1><section class='panel'><h2>Add employee</h2><form method='post' action='app'><input type='hidden' name='csrf' value='"+csrf(q.getSession())+"'><input type='hidden' name='action' value='employee'><div class='grid'><label>Employee code<input name='code' required></label><label>First name<input name='first' required></label><label>Last name<input name='last' required></label><label>Email<input name='email' type='email' required></label><label>Job title<input name='job' required></label><label>Joining date<input name='joining' type='date' required></label><label>Department ID<input name='department' type='number'></label></div><button>Add employee</button></form></section>"+table(c,"SELECT e.id,e.employee_code,e.first_name,e.last_name,e.email,e.job_title,e.joining_date,e.status,COALESCE(d.name,'—') department FROM employees e LEFT JOIN departments d ON d.id=e.department_id ORDER BY e.id DESC","Employee directory","deleteEmployee",q.getSession()); }
            else if(module.equals("departments")){require(role,"ADMIN","HR_STAFF");content="<h1>Departments</h1><section class='panel'><form method='post' action='app'><input type='hidden' name='csrf' value='"+csrf(q.getSession())+"'><input type='hidden' name='action' value='department'><label>Department name<input name='name' required></label><label>Description<input name='description'></label><button>Add department</button></form></section>"+table(c,"SELECT d.id,d.name,d.description,d.active,COUNT(e.id) employees FROM departments d LEFT JOIN employees e ON e.department_id=d.id GROUP BY d.id ORDER BY d.name","Department list","deleteDepartment",q.getSession());}
            else if(module.equals("attendance")){require(role,"ADMIN","HR_STAFF");content="<h1>Attendance</h1><section class='panel'><form method='post' action='app'><input type='hidden' name='csrf' value='"+csrf(q.getSession())+"'><input type='hidden' name='action' value='attendance'><label>Employee ID<input name='employee' type='number' required></label><label>Date<input name='date' type='date' required></label><label>Status<select name='status'><option>PRESENT</option><option>ABSENT</option><option>HALF_DAY</option><option>LEAVE</option></select></label><button>Record attendance</button></form><p class='muted'>Find employee IDs in the employee directory. One record per employee per date.</p></section>"+table(c,"SELECT a.id,a.employee_id,e.employee_code,CONCAT(e.first_name,' ',e.last_name) employee,a.attendance_date,a.status FROM attendance a JOIN employees e ON e.id=a.employee_id ORDER BY a.attendance_date DESC LIMIT 100","Recent attendance","deleteAttendance",q.getSession());}
            else if(module.equals("leaves")){require(role,"ADMIN","HR_STAFF");content="<h1>Leave requests</h1><section class='panel'><h2>Submit a request</h2><form method='post' action='app'><input type='hidden' name='csrf' value='"+csrf(q.getSession())+"'><input type='hidden' name='action' value='leave'><label>Employee ID<input name='employee' type='number' required></label><label>Start<input name='start' type='date' required></label><label>End<input name='end' type='date' required></label><label>Reason<input name='reason' required></label><button>Submit request</button></form></section>"+table(c,"SELECT l.id,l.employee_id,CONCAT(e.first_name,' ',e.last_name) employee,l.start_date,l.end_date,l.reason,l.status FROM leave_requests l JOIN employees e ON e.id=l.employee_id ORDER BY l.created_at DESC","Requests","deleteLeave",q.getSession());if(role.equals("ADMIN")||role.equals("HR_STAFF"))content+="<section class='panel'><h2>Review request</h2><form method='post' action='app'><input type='hidden' name='csrf' value='"+csrf(q.getSession())+"'><input type='hidden' name='action' value='review'><label>Request ID<input name='id' type='number' required></label><label>Decision<select name='decision'><option>APPROVED</option><option>REJECTED</option></select></label><button>Save decision</button></form></section>";}
            else if(module.equals("payroll")){require(role,"ADMIN","PAYROLL_STAFF");content="<h1>Payroll</h1><section class='panel'><h2>Generate monthly payroll</h2><form method='post' action='app'><input type='hidden' name='csrf' value='"+csrf(q.getSession())+"'><input type='hidden' name='action' value='payroll'><label>Employee ID<input name='employee' type='number' required></label><label>Month<input name='month' type='month' required></label><button>Generate payroll</button></form><p class='muted'>Uses the salary structure effective on the first day of the chosen month. Duplicate months are rejected.</p></section>"+table(c,"SELECT p.id,p.employee_id,e.employee_code,DATE_FORMAT(p.payroll_month,'%Y-%m') month,p.basic,p.hra,p.other_allowances,p.bonus,p.deductions,p.gross,p.net,p.status FROM payroll p JOIN employees e ON e.id=p.employee_id ORDER BY p.payroll_month DESC","Payroll records","deletePayroll",q.getSession());}
            else if(module.equals("salaries")){require(role,"ADMIN","PAYROLL_STAFF");content="<h1>Salary structures</h1><section class='panel'><h2>Add effective salary structure</h2><form method='post' action='app'><input type='hidden' name='csrf' value='"+csrf(q.getSession())+"'><input type='hidden' name='action' value='salary'><div class='grid'><label>Employee ID<input name='employee' type='number' required></label><label>Basic salary<input name='basic' type='number' min='0' step='0.01' required></label><label>HRA<input name='hra' type='number' min='0' step='0.01' value='0' required></label><label>Other allowances<input name='other' type='number' min='0' step='0.01' value='0' required></label><label>Bonus<input name='bonus' type='number' min='0' step='0.01' value='0' required></label><label>Monthly deductions<input name='deductions' type='number' min='0' step='0.01' value='0' required></label><label>Effective from<input name='effective' type='date' required></label></div><button>Save structure</button></form><p class='muted'>The employee ID is shown in the employee directory. Older structures remain available for historical payroll.</p></section>"+table(c,"SELECT s.id,s.employee_id,e.employee_code,s.basic,s.hra,s.other_allowances,s.bonus,s.deductions,s.effective_start,s.effective_end FROM salary_structures s JOIN employees e ON e.id=s.employee_id ORDER BY s.effective_start DESC","Salary history","deleteSalary",q.getSession());}
            else if(module.equals("payslips")){require(role,"ADMIN","PAYROLL_STAFF");content="<h1>Payslips</h1><p class='muted'>Payslips use the saved payroll amounts, even if a salary structure changes later.</p>"+table(c,"SELECT p.id,p.employee_id,e.employee_code,CONCAT(e.first_name,' ',e.last_name) employee,DATE_FORMAT(p.payroll_month,'%Y-%m') month,p.gross,p.net,p.status FROM payroll p JOIN employees e ON e.id=p.employee_id ORDER BY p.payroll_month DESC","Saved payroll slips","deletePayroll",q.getSession())+"<section class='panel'><p>Open a saved payslip by its payroll record ID:</p><form method='get' action='app'><input type='hidden' name='view' value='payslip'><label>Payroll record ID<input name='id' type='number' required></label><button>View payslip</button></form></section>";}
            else if(module.equals("payslip")){require(role,"ADMIN","PAYROLL_STAFF");long id=Long.parseLong(q.getParameter("id"));try(PreparedStatement p=c.prepareStatement("SELECT e.employee_code,e.first_name,e.last_name,COALESCE(d.name,'—'),e.job_title,DATE_FORMAT(p.payroll_month,'%M %Y'),p.basic,p.hra,p.other_allowances,p.bonus,p.deductions,p.gross,p.net FROM payroll p JOIN employees e ON e.id=p.employee_id LEFT JOIN departments d ON d.id=e.department_id WHERE p.id=?")){p.setLong(1,id);try(ResultSet x=p.executeQuery()){if(!x.next()){r.sendError(404);return;}content="<article class='panel payslip'><p class='muted'>DEMO COMPANY</p><h1>Payslip · "+esc(x.getString(6))+"</h1><p>"+esc(x.getString(2))+" "+esc(x.getString(3))+" · "+esc(x.getString(1))+"</p><p>"+esc(x.getString(4))+" · "+esc(x.getString(5))+"</p><table><tbody><tr><th>Basic salary</th><td>₹"+esc(x.getString(7))+"</td></tr><tr><th>HRA</th><td>₹"+esc(x.getString(8))+"</td></tr><tr><th>Other allowances</th><td>₹"+esc(x.getString(9))+"</td></tr><tr><th>Bonus</th><td>₹"+esc(x.getString(10))+"</td></tr><tr><th>Gross salary</th><td>₹"+esc(x.getString(12))+"</td></tr><tr><th>Total deductions</th><td>₹"+esc(x.getString(11))+"</td></tr><tr><th>Net salary</th><td><b>₹"+esc(x.getString(13))+"</b></td></tr></tbody></table><button onclick='window.print()' class='no-print'>Print payslip</button></article>";}}}
            else if(module.equals("reports")){require(role,"ADMIN","HR_STAFF","PAYROLL_STAFF"); content="<h1>Reports</h1><div class='cards'>"+card(c,"Active employees","SELECT COUNT(*) FROM employees WHERE status='ACTIVE'")+card(c,"Pending leave","SELECT COUNT(*) FROM leave_requests WHERE status='PENDING'")+card(c,"Payroll net this month","SELECT COALESCE(SUM(net),0) FROM payroll WHERE payroll_month=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')")+"</div>"+table(c,"SELECT d.name department,COUNT(e.id) employees FROM departments d LEFT JOIN employees e ON e.department_id=d.id AND e.status='ACTIVE' GROUP BY d.id ORDER BY d.name","Employees by department")+table(c,"SELECT DATE_FORMAT(attendance_date,'%Y-%m') month,status,COUNT(*) records FROM attendance GROUP BY month,status ORDER BY month DESC","Monthly attendance");}
            else {r.sendError(404);return;}
            page(r,"Workspace",menu+"<div class='userline'>Signed in as <b>"+esc(user.toString())+"</b> · "+esc(role)+"</div>"+(q.getParameter("message")!=null?"<p class='notice'>"+esc(q.getParameter("message"))+"</p>":"")+content);
        } catch(SecurityException ex){r.sendError(403);} catch(Exception ex){getServletContext().log("Unable to load application page",ex);page(r,"Service unavailable",menu+"<h1>Could not load this page</h1><p>Check the database configuration and server log. No credentials are shown here.</p>");}
    }
    private void require(String role,String...allowed){for(String a:allowed)if(a.equals(role))return;throw new SecurityException();}
    private String card(Connection c,String title,String sql)throws SQLException {try(Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return "<section class='card'><span>"+esc(title)+"</span><strong>"+esc(r.getString(1))+"</strong></section>";}}
    private String table(Connection c,String sql,String title)throws SQLException {return table(c,sql,title,null,null);}
    private String table(Connection c,String sql,String title,String deleteAction,HttpSession session)throws SQLException {StringBuilder b=new StringBuilder("<section class='panel'><h2>"+esc(title)+"</h2><div class='tablewrap'><table>");try(Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){ResultSetMetaData m=r.getMetaData();b.append("<thead><tr>");for(int i=1;i<=m.getColumnCount();i++)b.append("<th>").append(esc(m.getColumnLabel(i))).append("</th>");if(deleteAction!=null)b.append("<th>Actions</th>");b.append("</tr></thead><tbody>");boolean any=false;while(r.next()){any=true;b.append("<tr>");long id=r.getLong(1);for(int i=1;i<=m.getColumnCount();i++)b.append("<td>").append(esc(r.getString(i))).append("</td>");if(deleteAction!=null)b.append("<td><form method='post' action='app' onsubmit=\"return confirm('Delete this record?')\"><input type='hidden' name='csrf' value='").append(esc(csrf(session))).append("'><input type='hidden' name='action' value='").append(esc(deleteAction)).append("'><input type='hidden' name='id' value='").append(id).append("'><button class='danger' type='submit'>Delete</button></form></td>");b.append("</tr>");}if(!any)b.append("<tr><td colspan='20'>No records yet.</td></tr>");}return b.append("</tbody></table></div></section>").toString();}
    @Override protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException {
        if(q.getServletPath().equals("/login")){login(q,r);return;} if(q.getSession().getAttribute("user")==null){r.sendRedirect("login");return;}
        if(q.getServletPath().equals("/logout")){HttpSession session=q.getSession(false);if(session==null||!csrf(session).equals(q.getParameter("csrf"))){r.sendError(403);return;}session.invalidate();r.sendRedirect("login");return;}
        HttpSession session=q.getSession();if(!csrf(session).equals(q.getParameter("csrf"))){r.sendError(403);return;}String role=(String)session.getAttribute("role"),action=q.getParameter("action");
        try(Connection c=DatabaseConnection.getConnection()) {
            switch(action==null?"":action){
                case "employee"->{require(role,"ADMIN","HR_STAFF");try(PreparedStatement p=c.prepareStatement("INSERT INTO employees(employee_code,first_name,last_name,email,job_title,joining_date,department_id) VALUES(?,?,?,?,?,?,?)")){p.setString(1,q.getParameter("code"));p.setString(2,q.getParameter("first"));p.setString(3,q.getParameter("last"));p.setString(4,q.getParameter("email"));p.setString(5,q.getParameter("job"));p.setDate(6,Date.valueOf(q.getParameter("joining")));String d=q.getParameter("department");if(d==null||d.isBlank())p.setNull(7,Types.BIGINT);else p.setLong(7,Long.parseLong(d));p.executeUpdate();}}
                case "department"->{require(role,"ADMIN","HR_STAFF");try(PreparedStatement p=c.prepareStatement("INSERT INTO departments(name,description) VALUES(?,?)")){p.setString(1,q.getParameter("name"));p.setString(2,q.getParameter("description"));p.executeUpdate();}}
                case "salary"->{require(role,"ADMIN","PAYROLL_STAFF");BigDecimal basic=money(q,"basic"),hra=money(q,"hra"),other=money(q,"other"),bonus=money(q,"bonus"),ded=money(q,"deductions");PayrollCalculator.calculate(basic,hra,other,bonus,ded);try(PreparedStatement p=c.prepareStatement("INSERT INTO salary_structures(employee_id,basic,hra,other_allowances,bonus,deductions,effective_start) VALUES(?,?,?,?,?,?,?)")){p.setLong(1,Long.parseLong(q.getParameter("employee")));p.setBigDecimal(2,basic);p.setBigDecimal(3,hra);p.setBigDecimal(4,other);p.setBigDecimal(5,bonus);p.setBigDecimal(6,ded);p.setDate(7,Date.valueOf(q.getParameter("effective")));p.executeUpdate();}}
                case "attendance"->{require(role,"ADMIN","HR_STAFF");try(PreparedStatement p=c.prepareStatement("INSERT INTO attendance(employee_id,attendance_date,status) VALUES(?,?,?)")){p.setLong(1,Long.parseLong(q.getParameter("employee")));p.setDate(2,Date.valueOf(q.getParameter("date")));p.setString(3,q.getParameter("status"));p.executeUpdate();}}
                case "leave"->{require(role,"ADMIN","HR_STAFF");LocalDate start=LocalDate.parse(q.getParameter("start")),end=LocalDate.parse(q.getParameter("end"));if(end.isBefore(start))throw new IllegalArgumentException("Leave end must not be before leave start.");try(PreparedStatement p=c.prepareStatement("INSERT INTO leave_requests(employee_id,start_date,end_date,reason) VALUES(?,?,?,?)")){p.setLong(1,Long.parseLong(q.getParameter("employee")));p.setDate(2,Date.valueOf(start));p.setDate(3,Date.valueOf(end));p.setString(4,q.getParameter("reason"));p.executeUpdate();}}
                case "review"->{require(role,"ADMIN","HR_STAFF");try(PreparedStatement p=c.prepareStatement("UPDATE leave_requests SET status=?,reviewed_by=(SELECT id FROM users WHERE username=?),reviewed_at=NOW() WHERE id=? AND status='PENDING'")){p.setString(1,q.getParameter("decision"));p.setString(2,session.getAttribute("user").toString());p.setLong(3,Long.parseLong(q.getParameter("id")));if(p.executeUpdate()==0)throw new IllegalArgumentException("Request was not found or has already been reviewed.");}}
                case "payroll"->{require(role,"ADMIN","PAYROLL_STAFF");long emp=Long.parseLong(q.getParameter("employee"));LocalDate month=LocalDate.parse(q.getParameter("month")+"-01");try(PreparedStatement p=c.prepareStatement("SELECT basic,hra,other_allowances,bonus,deductions FROM salary_structures WHERE employee_id=? AND effective_start<=? AND (effective_end IS NULL OR effective_end>=?) ORDER BY effective_start DESC LIMIT 1")){p.setLong(1,emp);p.setDate(2,Date.valueOf(month));p.setDate(3,Date.valueOf(month));try(ResultSet s=p.executeQuery()){if(!s.next())throw new IllegalArgumentException("No salary structure applies to this employee for that month.");BigDecimal basic=s.getBigDecimal(1),hra=s.getBigDecimal(2),other=s.getBigDecimal(3),bonus=s.getBigDecimal(4),ded=s.getBigDecimal(5);var totals=PayrollCalculator.calculate(basic,hra,other,bonus,ded);try(PreparedStatement ins=c.prepareStatement("INSERT INTO payroll(employee_id,payroll_month,basic,hra,other_allowances,bonus,deductions,gross,net) VALUES(?,?,?,?,?,?,?,?,?)")){ins.setLong(1,emp);ins.setDate(2,Date.valueOf(month));ins.setBigDecimal(3,basic);ins.setBigDecimal(4,hra);ins.setBigDecimal(5,other);ins.setBigDecimal(6,bonus);ins.setBigDecimal(7,ded);ins.setBigDecimal(8,totals.gross());ins.setBigDecimal(9,totals.net());ins.executeUpdate();}}}}
                case "deleteEmployee"->{require(role,"ADMIN","HR_STAFF");long id=Long.parseLong(q.getParameter("id"));try(PreparedStatement p=c.prepareStatement("SELECT (SELECT COUNT(*) FROM attendance WHERE employee_id=?)+(SELECT COUNT(*) FROM leave_requests WHERE employee_id=?)+(SELECT COUNT(*) FROM salary_structures WHERE employee_id=?)+(SELECT COUNT(*) FROM payroll WHERE employee_id=?)")){for(int i=1;i<=4;i++)p.setLong(i,id);try(ResultSet x=p.executeQuery()){x.next();if(x.getLong(1)>0)throw new IllegalArgumentException("Cannot delete an employee with linked attendance, leave, salary, or payroll records. Delete those records first.");}}deleteById(c,"employees",id);}
                case "deleteDepartment"->{require(role,"ADMIN","HR_STAFF");deleteById(c,"departments",Long.parseLong(q.getParameter("id")));}
                case "deleteAttendance"->{require(role,"ADMIN","HR_STAFF");deleteById(c,"attendance",Long.parseLong(q.getParameter("id")));}
                case "deleteLeave"->{require(role,"ADMIN","HR_STAFF");deleteById(c,"leave_requests",Long.parseLong(q.getParameter("id")));}
                case "deleteSalary"->{require(role,"ADMIN","PAYROLL_STAFF");deleteById(c,"salary_structures",Long.parseLong(q.getParameter("id")));}
                case "deletePayroll"->{require(role,"ADMIN","PAYROLL_STAFF");deleteById(c,"payroll",Long.parseLong(q.getParameter("id")));}
                default->throw new IllegalArgumentException("Unknown action.");
            }
            r.sendRedirect("app?view="+switch(action){case "employee","deleteEmployee"->"employees";case "department","deleteDepartment"->"departments";case "attendance","deleteAttendance"->"attendance";case "leave","review","deleteLeave"->"leaves";case "salary","deleteSalary"->"salaries";case "deletePayroll"->"payslips";default->"payroll";}+"&message="+(action.startsWith("delete")?"Deleted":"Saved"));
        } catch(SecurityException ex){r.sendError(403);} catch(IllegalArgumentException ex){page(r,"Could not save", "<h1>Could not save that information</h1><p>"+esc(ex.getMessage())+"</p><a href='app'>Back to overview</a>");} catch(Exception ex){getServletContext().log("Unable to save submitted information",ex);page(r,"Could not save", "<h1>Could not save that information</h1><p>Check required fields, dates, IDs and duplicate records, then try again.</p><a href='app'>Back to overview</a>");}
    }
    private void deleteById(Connection c,String table,long id)throws SQLException {String sql=switch(table){case "employees"->"DELETE FROM employees WHERE id=?";case "departments"->"DELETE FROM departments WHERE id=?";case "attendance"->"DELETE FROM attendance WHERE id=?";case "leave_requests"->"DELETE FROM leave_requests WHERE id=?";case "salary_structures"->"DELETE FROM salary_structures WHERE id=?";case "payroll"->"DELETE FROM payroll WHERE id=?";default->throw new IllegalArgumentException("Unsupported delete action.");};try(PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,id);if(p.executeUpdate()!=1)throw new IllegalArgumentException("That record no longer exists.");}}
    private BigDecimal money(HttpServletRequest q,String name){BigDecimal amount=new BigDecimal(q.getParameter(name));if(amount.signum()<0)throw new IllegalArgumentException("Salary components cannot be negative.");return amount.setScale(2,java.math.RoundingMode.HALF_UP);}
    private void login(HttpServletRequest q,HttpServletResponse r)throws IOException {try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT password_hash,role FROM users WHERE username=? AND active=1")){p.setString(1,q.getParameter("username"));try(ResultSet s=p.executeQuery()){if(s.next()&&PasswordUtil.verify(q.getParameter("password"),s.getString(1))){HttpSession session=q.getSession(true);q.changeSessionId();session.setAttribute("user",q.getParameter("username"));session.setAttribute("role",s.getString(2));session.setMaxInactiveInterval(30*60);r.sendRedirect("app");return;}}}catch(Exception ex){getServletContext().log("Login service unavailable",ex);}r.sendRedirect("login?error=1");}
}
